-- LOCAL PRO ONLY. Private CRM gateway preserves exact legacy payloads/receipts.
-- Atomic manual opportunity + optional channel; no directory-card fabrication,
-- appointment, account, quote, work, acceptance, debt, notification or delivery.
begin;
create table if not exists pro_lead_origin_creates(owner_id uuid not null references profiles(id)on delete cascade,action_id uuid not null,lead_kind text not null default'manual'check(lead_kind='manual'),lead_id uuid not null,core_action_id uuid not null,input jsonb not null,result jsonb not null,at timestamptz not null default now(),primary key(owner_id,action_id),unique(owner_id,lead_id),unique(owner_id,core_action_id),foreign key(owner_id,lead_kind,lead_id)references pro_lead_center_records(owner_id,kind,id)on delete cascade);
create or replace function public.pro_lead_private_core_action_read(p_actor uuid,p_action uuid) returns jsonb language plpgsql stable security invoker set search_path=public,pg_temp as $$declare r pro_lead_center_actions;begin perform pro_lead_origin_owner(p_actor);select * into r from pro_lead_center_actions where owner_id=p_actor and action_id=p_action;if not found then return jsonb_build_object('receipt',null);end if;perform pro_lead_origin_item(p_actor,r.input->>'kind',(r.input->>'id')::uuid);return jsonb_build_object('receipt',jsonb_build_object('input',r.input,'result',r.result));end $$;
create or replace function public.pro_lead_private_core_materialize(p_actor uuid)returns void language plpgsql security invoker set search_path=public,pg_temp as $$begin perform pro_lead_origin_owner(p_actor);perform pro_lead_center_catalog_materialize(p_actor);end $$;
create or replace function public.pro_lead_private_core_mutate(p_actor uuid,p_input jsonb) returns jsonb language plpgsql security invoker set search_path=public,pg_temp as $$declare aid uuid;lid uuid;act text;k text;expected text[];rev integer;catalog_revision integer;r pro_lead_center_records;prior pro_lead_center_actions;c pro_clients;before_json jsonb;after_json jsonb;answer jsonb;forecast jsonb;day date;sid text;mode_value text;before_name text;after_name text;begin
 perform pro_lead_origin_owner(p_actor);
 if jsonb_typeof(p_input) is distinct from 'object' or jsonb_typeof(p_input->'action') is distinct from 'string' or jsonb_typeof(p_input->'kind') is distinct from 'string' or jsonb_typeof(p_input->'actionId') is distinct from 'string' or jsonb_typeof(p_input->'id') is distinct from 'string' or jsonb_typeof(p_input->'revision') is distinct from 'number' or not coalesce(p_input->>'revision'~'^[0-9]{1,10}$',false) or(p_input->>'revision')::numeric not between 0 and 2147483646 then raise exception 'Invalid opportunity operation' using errcode='22023';end if;
 act:=p_input->>'action';k:=p_input->>'kind';aid:=(p_input->>'actionId')::uuid;lid:=(p_input->>'id')::uuid;rev:=(p_input->>'revision')::integer;
 expected:=case act when 'create' then array['action','actionId','address','catalogRevision','clientId','description','forecast','id','kind','revision','sourceLabel','stageId','stageMode','title'] when 'update' then array['action','actionId','address','clientId','description','forecast','id','kind','revision','sourceLabel','title'] when 'set_stage' then array['action','actionId','catalogRevision','id','kind','revision','stageId'] when 'return_auto' then array['action','actionId','catalogRevision','id','kind','revision'] when 'archive' then array['action','actionId','id','kind','revision'] when 'restore' then array['action','actionId','id','kind','revision'] else null end;
 if aid is null or lid is null or expected is null or(select array_agg(key order by key) from jsonb_object_keys(p_input)key) is distinct from expected or k not in('manual','request') or k='request' and act not in('archive','restore') then raise exception 'Invalid source or fields' using errcode='22023';end if;
 -- Matches the existing contact writer: owner advisory precedes contact rows.
 -- No public request/work row is ever locked or updated by these private actions.
 perform pg_advisory_xact_lock(hashtextextended(p_actor::text,0));perform pg_advisory_xact_lock(hashtextextended('pro-lead-center-action:'||p_actor::text||':'||aid::text,0));perform pg_advisory_xact_lock(hashtextextended('pro-request-pipeline-catalog:'||p_actor::text,0));perform pro_lead_origin_owner(p_actor);
 select * into prior from pro_lead_center_actions where owner_id=p_actor and action_id=aid;if found then if prior.input is distinct from p_input then raise exception 'Opportunity action reused' using errcode='22023';end if;perform pro_lead_private_core_action_read(p_actor,aid);return prior.result;end if;
 if exists(select 1 from pro_lead_center_catalog_actions where owner_id=p_actor and action_id=aid) or exists(select 1 from pro_request_pipeline_actions where owner_id=p_actor and action_id=aid)or exists(select 1 from pro_lead_origin_creates where owner_id=p_actor and action_id=aid)or exists(select 1 from pro_lead_origin_actions where owner_id=p_actor and action_id=aid) then raise exception 'Action identity already used' using errcode='40001';end if;
 catalog_revision:=(pro_lead_origin_stage_catalog(p_actor)->>'revision')::integer;
 if act in('create','set_stage','return_auto') then if jsonb_typeof(p_input->'catalogRevision') is distinct from 'number' or not coalesce(p_input->>'catalogRevision'~'^[0-9]{1,10}$',false) or(p_input->>'catalogRevision')::numeric not between 0 and 2147483646 then raise exception 'Invalid catalogue revision' using errcode='22023';end if;if catalog_revision<>(p_input->>'catalogRevision')::integer then raise exception 'Lead stages changed' using errcode='40001';end if;end if;
 if k='request' and not exists(select 1 from pro_appointment_requests where owner_id=p_actor and id=lid) then raise exception 'Request unavailable' using errcode='42501';end if;
 select * into r from pro_lead_center_records where owner_id=p_actor and kind=k and id=lid for update;
 if act='create' then if found or rev<>0 then raise exception 'Opportunity identity used' using errcode='40001';end if;
 else
  if k='manual' and not found then raise exception 'Opportunity unavailable' using errcode='42501';end if;
  before_json:=pro_lead_origin_item(p_actor,k,lid);if coalesce(r.revision,0)<>rev then raise exception 'Opportunity changed' using errcode='40001';end if;
  if act not in('archive','restore') and r.archived then raise exception 'Restore before editing' using errcode='40001';end if;
 end if;
 if act in('create','update') then
  if jsonb_typeof(p_input->'clientId') is distinct from 'string' or length(p_input->>'clientId') not between 1 and 160 or jsonb_typeof(p_input->'title') is distinct from 'string' or length(btrim(p_input->>'title')) not between 1 and 160 or jsonb_typeof(p_input->'description') is distinct from 'string' or length(p_input->>'description')>2000 or jsonb_typeof(p_input->'address') is distinct from 'string' or length(p_input->>'address')>500 or jsonb_typeof(p_input->'sourceLabel') is distinct from 'string' or length(p_input->>'sourceLabel')>80 then raise exception 'Invalid opportunity details' using errcode='22023';end if;
  select * into c from pro_clients where user_id=p_actor and id=p_input->>'clientId' for share;if not found or c.archived and(act='create' or c.id is distinct from r.client_id) then raise exception 'Choose an active owned customer' using errcode='40001';end if;
  forecast:=p_input->'forecast';if jsonb_typeof(forecast) is distinct from 'object' or(select array_agg(key order by key) from jsonb_object_keys(forecast)key) is distinct from array['budgetCents','currency','expectedStart','profitCents','projectType','revenueCents'] or jsonb_typeof(forecast->'projectType') is distinct from 'string' or length(forecast->>'projectType')>80 or jsonb_typeof(forecast->'currency') is distinct from 'string' or forecast->>'currency' not in('CRC','USD') or jsonb_typeof(forecast->'expectedStart') not in('string','null') then raise exception 'Invalid private forecast' using errcode='22023';end if;
  if forecast->>'expectedStart' is not null then if not(forecast->>'expectedStart'~'^[0-9]{4}-[0-9]{2}-[0-9]{2}$') then raise exception 'Invalid expected date' using errcode='22023';end if;day:=(forecast->>'expectedStart')::date;if day not between date'1900-01-01' and date'2100-12-31' then raise exception 'Expected date out of range' using errcode='22023';end if;end if;
  if exists(select 1 from jsonb_each(forecast)f where key in('revenueCents','budgetCents','profitCents') and value<>'null'::jsonb and(jsonb_typeof(value)<>'number' or value::text!~'^-?[0-9]{1,13}$' or abs((value::text)::numeric)>1000000000000 or key<>'profitCents' and(value::text)::numeric<0)) then raise exception 'Invalid private money estimate' using errcode='22023';end if;
  if act='create' then mode_value:=p_input->>'stageMode';sid:=p_input->>'stageId';if jsonb_typeof(p_input->'stageMode') is distinct from 'string' or mode_value not in('automatic','manual') or jsonb_typeof(p_input->'stageId') not in('string','null') or(mode_value='manual')<>(sid is not null) then raise exception 'Invalid initial commercial stage' using errcode='22023';end if;
   if sid is not null then perform pro_lead_private_core_materialize(p_actor);if not exists(select 1 from pro_request_pipeline_stages where owner_id=p_actor and id=sid and not hidden and not retired) then raise exception 'Choose a visible stage' using errcode='40001';end if;end if;
   insert into pro_lead_center_records(owner_id,kind,id,client_id,title,description,address,source_label,project_type,expected_start,currency,revenue_cents,budget_cents,profit_cents,stage_mode,stage_id,revision) values(p_actor,'manual',lid,c.id,btrim(p_input->>'title'),btrim(p_input->>'description'),btrim(p_input->>'address'),btrim(p_input->>'sourceLabel'),btrim(forecast->>'projectType'),day,forecast->>'currency',(forecast->>'revenueCents')::bigint,(forecast->>'budgetCents')::bigint,(forecast->>'profitCents')::bigint,mode_value,sid,1);
  else update pro_lead_center_records set client_id=c.id,title=btrim(p_input->>'title'),description=btrim(p_input->>'description'),address=btrim(p_input->>'address'),source_label=btrim(p_input->>'sourceLabel'),project_type=btrim(forecast->>'projectType'),expected_start=day,currency=forecast->>'currency',revenue_cents=(forecast->>'revenueCents')::bigint,budget_cents=(forecast->>'budgetCents')::bigint,profit_cents=(forecast->>'profitCents')::bigint,revision=revision+1,updated_at=now() where owner_id=p_actor and kind='manual' and id=lid;end if;
 elsif act in('set_stage','return_auto') then
  sid:=case when act='set_stage' then p_input->>'stageId' else null end;if act='set_stage' then perform pro_lead_private_core_materialize(p_actor);if sid is null or not exists(select 1 from pro_request_pipeline_stages where owner_id=p_actor and id=sid and not hidden and not retired) then raise exception 'Choose a visible stage' using errcode='40001';end if;end if;
  update pro_lead_center_records set stage_mode=case when act='set_stage' then 'manual' else 'automatic' end,stage_id=sid,revision=revision+1,updated_at=now() where owner_id=p_actor and kind='manual' and id=lid;
 else
  if coalesce(r.archived,false)=(act='archive') then raise exception 'Opportunity archive state changed' using errcode='40001';end if;
  if k='request' and r.id is null then insert into pro_lead_center_records(owner_id,kind,id,request_id,revision,archived) values(p_actor,'request',lid,lid,1,true);
  else update pro_lead_center_records set archived=(act='archive'),revision=revision+1,updated_at=now() where owner_id=p_actor and kind=k and id=lid;end if;
 end if;
 perform pro_lead_origin_owner(p_actor);
 if k='request' then select * into r from pro_lead_center_records where owner_id=p_actor and kind='request' and id=lid;after_json:=jsonb_set(before_json,'{preference}',jsonb_build_object('revision',r.revision,'archived',r.archived,'updatedAt',r.updated_at));else after_json:=pro_lead_origin_item(p_actor,k,lid);end if;
 select name into before_name from pro_request_pipeline_stages where owner_id=p_actor and id=before_json->'manual'->>'stageId';select name into after_name from pro_request_pipeline_stages where owner_id=p_actor and id=after_json->'manual'->>'stageId';
 answer:=jsonb_build_object('action',act,'item',after_json,'before',before_json,'catalogRevision',catalog_revision);insert into pro_lead_center_history values(p_actor,k,lid,aid,act,before_json,after_json,before_name,after_name,now());insert into pro_lead_center_actions values(p_actor,aid,p_input,answer,pro_team_name(p_actor),now());perform pro_lead_origin_owner(p_actor);return answer;end $$;
create or replace function public.pro_lead_private_core_history_read(p_actor uuid,p_kind text,p_id uuid,p_after uuid default null) returns jsonb language plpgsql stable security invoker set search_path=public,pg_temp as $$declare items jsonb;anchor_revision integer;cursor_id uuid;begin
 perform pro_lead_origin_item(p_actor,p_kind,p_id);
 if p_after is not null then select coalesce((after_item->'manual'->>'revision')::integer,(after_item->'preference'->>'revision')::integer) into anchor_revision from pro_lead_center_history where owner_id=p_actor and kind=p_kind and id=p_id and action_id=p_after;if not found then raise exception 'Lead history cursor unavailable' using errcode='40001';end if;end if;
 select coalesce(jsonb_agg(jsonb_build_object('actionId',h.action_id,'action',h.action,'at',h.at,'before',h.before_item,'after',h.after_item,'beforeName',h.before_name,'afterName',h.after_name) order by coalesce((h.after_item->'manual'->>'revision')::integer,(h.after_item->'preference'->>'revision')::integer) desc),'[]'::jsonb) into items from(select * from pro_lead_center_history where owner_id=p_actor and kind=p_kind and id=p_id and(p_after is null or coalesce((after_item->'manual'->>'revision')::integer,(after_item->'preference'->>'revision')::integer)<anchor_revision) order by coalesce((after_item->'manual'->>'revision')::integer,(after_item->'preference'->>'revision')::integer) desc limit 21)h;
 if jsonb_array_length(items)>20 then cursor_id:=(items->19->>'actionId')::uuid;items:=items-20;end if;return jsonb_build_object('items',items,'nextCursor',cursor_id);end $$;
create or replace function public.pro_lead_private_core_detail(p_actor uuid,p_kind text,p_id uuid) returns jsonb language plpgsql stable security invoker set search_path=public,pg_temp as $$declare item jsonb;history jsonb;begin item:=pro_lead_origin_item(p_actor,p_kind,p_id);history:=pro_lead_private_core_history_read(p_actor,p_kind,p_id);return jsonb_build_object('catalog',pro_lead_origin_stage_catalog(p_actor),'item',item,'history',history->'items','nextCursor',history->'nextCursor');end $$;
create or replace function public.pro_lead_private_core_read(p_actor uuid,p_status text default'active',p_stage text default null,p_query text default'',p_after text default null,p_snapshot text default null)returns jsonb language sql stable security invoker set search_path=public,pg_temp as $$select pro_lead_origin_list(p_actor,p_status,p_stage,p_query,null,p_after,p_snapshot)->'page'$$;
create or replace function public.pro_lead_origin_create_current(p_actor uuid,p_lead uuid)returns jsonb language sql stable security invoker set search_path=public,pg_temp as $$select jsonb_build_object('item',pro_lead_origin_item(p_actor,'manual',p_lead),'origin',pro_lead_origin_get(p_actor,'manual',p_lead))$$;
create or replace function public.pro_lead_origin_create_action_read(p_actor uuid,p_action uuid)returns jsonb language plpgsql stable security invoker set search_path=public,pg_temp as $$declare r pro_lead_origin_creates;begin
 perform pro_lead_origin_owner(p_actor);select*into r from pro_lead_origin_creates where owner_id=p_actor and action_id=p_action;if not found then return jsonb_build_object('receipt',null);end if;perform pro_lead_origin_create_current(p_actor,r.lead_id);return jsonb_build_object('receipt',jsonb_build_object('input',r.input,'result',r.result));end $$;
create or replace function public.pro_lead_origin_create(p_actor uuid,p_input jsonb)returns jsonb language plpgsql security invoker set search_path=public,pg_temp as $$declare aid uuid;core_aid uuid;lid uuid;lead_input jsonb;channel jsonb;cid text;channel_rev integer;prior pro_lead_origin_creates;lead_result jsonb;origin_result jsonb;answer jsonb;begin
 perform pro_lead_origin_owner(p_actor);
 if jsonb_typeof(p_input)is distinct from'object'or not(p_input?&array['action','actionId','lead','channel'])or exists(select 1 from jsonb_object_keys(p_input)key where key<>all(array['action','actionId','lead','channel']))or p_input->>'action'is distinct from'create_lead'or jsonb_typeof(p_input->'actionId')is distinct from'string'or jsonb_typeof(p_input->'lead')is distinct from'object'or jsonb_typeof(p_input->'channel')not in('null','object')then raise exception'Invalid combined creation'using errcode='22023';end if;
 aid:=(p_input->>'actionId')::uuid;lead_input:=p_input->'lead';channel:=p_input->'channel';
 if lead_input->>'action'is distinct from'create'or lead_input->>'kind'is distinct from'manual'or jsonb_typeof(lead_input->'actionId')is distinct from'string'or jsonb_typeof(lead_input->'id')is distinct from'string'or jsonb_typeof(lead_input->'revision')is distinct from'number'or lead_input->>'revision'<>'0'then raise exception'Invalid manual creation'using errcode='22023';end if;
 core_aid:=(lead_input->>'actionId')::uuid;lid:=(lead_input->>'id')::uuid;if aid=core_aid then raise exception'Parent and child action identities must differ'using errcode='22023';end if;
 if channel<>'null'::jsonb then
 if not(channel?&array['id','revision'])or exists(select 1 from jsonb_object_keys(channel)key where key<>all(array['id','revision']))or jsonb_typeof(channel->'id')is distinct from'string'or jsonb_typeof(channel->'revision')is distinct from'number'or not coalesce(channel->>'revision'~'^[0-9]{1,10}$',false)or(channel->>'revision')::numeric not between 0 and 2147483647 then raise exception'Invalid chosen channel'using errcode='22023';end if;cid:=channel->>'id';channel_rev:=(channel->>'revision')::integer;end if;
 -- All relevant private writers use owner before child action/catalog locks.
 perform pg_advisory_xact_lock(hashtextextended(p_actor::text,0));perform pg_advisory_xact_lock(hashtextextended('pro-lead-origin-create:'||p_actor::text||':'||aid::text,0));perform pg_advisory_xact_lock(hashtextextended('pro-lead-center-action:'||p_actor::text||':'||core_aid::text,0));perform pg_advisory_xact_lock(hashtextextended('pro-lead-origin-action:'||p_actor::text||':'||aid::text,0));perform pg_advisory_xact_lock(hashtextextended('pro-request-pipeline-catalog:'||p_actor::text,0));perform pg_advisory_xact_lock(hashtextextended('pro-lead-origin-catalog:'||p_actor::text,0));perform pro_lead_origin_owner(p_actor);
 select*into prior from pro_lead_origin_creates where owner_id=p_actor and action_id=aid;if found then perform pro_lead_origin_create_current(p_actor,prior.lead_id);if prior.input is distinct from p_input then raise exception'Creation action reused'using errcode='22023';end if;return prior.result;end if;
 -- There is no partial-success adoption: the complete transaction owns every child.
 if exists(select 1 from pro_lead_center_actions where owner_id=p_actor and action_id=aid)or exists(select 1 from pro_lead_center_catalog_actions where owner_id=p_actor and action_id=aid)or exists(select 1 from pro_request_pipeline_actions where owner_id=p_actor and action_id=aid)or exists(select 1 from pro_lead_center_records where owner_id=p_actor and kind='manual'and id=lid)or exists(select 1 from pro_lead_center_actions where owner_id=p_actor and action_id=core_aid)or exists(select 1 from pro_lead_center_catalog_actions where owner_id=p_actor and action_id=core_aid)or exists(select 1 from pro_request_pipeline_actions where owner_id=p_actor and action_id=core_aid)or exists(select 1 from pro_lead_origin_actions where owner_id=p_actor and action_id=aid)or exists(select 1 from pro_lead_origin_assignments where owner_id=p_actor and kind='manual'and id=lid)then raise exception'Existing lead or child action has no combined origin'using errcode='40001';end if;
 if cid is not null then origin_result:=pro_lead_origin_channel_json(p_actor,cid);if origin_result is null or(origin_result->>'archived')::boolean or(origin_result->>'revision')::integer<>channel_rev then raise exception'Choose a current active channel'using errcode='40001';end if;end if;
 lead_result:=pro_lead_private_core_mutate(p_actor,lead_input);origin_result:=null;
 if cid is not null then origin_result:=pro_lead_origin_mutate(p_actor,jsonb_build_object('action','assign','actionId',aid,'kind','manual','id',lid,'revision',0,'channelId',cid,'channelRevision',channel_rev));end if;
 perform pro_lead_origin_owner(p_actor);if not(pro_lead_origin_get(p_actor,'manual',lid)->>'canWrite')::boolean then raise exception'Lead became read-only'using errcode='40001';end if;
 answer:=jsonb_build_object('action','create_lead','lead',lead_result,'origin',origin_result);insert into pro_lead_origin_creates(owner_id,action_id,lead_id,core_action_id,input,result)values(p_actor,aid,lid,core_aid,p_input,answer);return answer;end $$;
-- A committed parent UUID cannot be stolen by a legacy writer that does not
-- know the new ledger. Its fresh state/history writes roll back with this error.
create or replace function public.pro_lead_origin_create_child_guard()returns trigger language plpgsql security invoker set search_path=public,pg_temp as $$begin if exists(select 1 from pro_lead_origin_creates where owner_id=new.owner_id and action_id=new.action_id)then raise exception'Combined parent action identity is reserved'using errcode='40001';end if;return new;end $$;
drop trigger if exists pro_lead_origin_create_core_action_guard on pro_lead_center_actions;
create trigger pro_lead_origin_create_core_action_guard before insert on pro_lead_center_actions for each row execute function pro_lead_origin_create_child_guard();
drop trigger if exists pro_lead_origin_create_origin_action_guard on pro_lead_origin_actions;
create trigger pro_lead_origin_create_origin_action_guard before insert on pro_lead_origin_actions for each row execute function pro_lead_origin_create_child_guard();
create or replace function public.pro_lead_origin_create_immutable()returns trigger language plpgsql security invoker set search_path=public,pg_temp as $$begin raise exception'Immutable combined creation receipt'using errcode='23514';end $$;
drop trigger if exists pro_lead_origin_create_immutable on pro_lead_origin_creates;
create trigger pro_lead_origin_create_immutable before update on pro_lead_origin_creates for each row execute function pro_lead_origin_create_immutable();
alter table pro_lead_origin_creates enable row level security;
revoke all on pro_lead_origin_creates from public,anon,authenticated;grant all on pro_lead_origin_creates to service_role;
do $$declare f record;begin for f in select p.oid::regprocedure signature from pg_proc p join pg_namespace n on n.oid=p.pronamespace where n.nspname='public'and(p.proname like'pro_lead_private_core_%'or p.proname in('pro_lead_origin_create','pro_lead_origin_create_current','pro_lead_origin_create_action_read','pro_lead_origin_create_immutable','pro_lead_origin_create_child_guard'))loop execute format('revoke all on function %s from public,anon,authenticated',f.signature);execute format('grant execute on function %s to service_role',f.signature);end loop;end $$;
commit;
notify pgrst,'reload schema';
